css:
:root{ --ink:#f4f7fb; --soft:rgba(244,247,251,.72); --chip:rgba(10,22,38,.62); --line:rgba(255,255,255,.16); --accent:#ff6b3d; --gold:#ffd25e;
  box-sizing:border-box; padding-top:env(safe-area-inset-top,0px); padding-bottom:env(safe-area-inset-bottom,0px); }
@media (prefers-color-scheme: light){ :root:not([data-theme="dark"]){ --ink:#f4f7fb; } }
:root[data-theme="light"]{ --ink:#f4f7fb; }
*,*::before,*::after{box-sizing:inherit}
html{height:100%; scroll-padding-top:env(safe-area-inset-top,0px)}
body{margin:0; height:100%; overflow:hidden; background:#0c1828; color:var(--ink); font-family:"Archivo",system-ui,sans-serif; -webkit-user-select:none; user-select:none}
#app{position:fixed; left:0; top:0; width:100vw; height:100vh; overflow:hidden}
#app.rot{width:100vh; height:100vw; transform-origin:0 0; transform:rotate(90deg) translateY(-100%)}
#cv{position:absolute; inset:0; width:100%; height:100%; touch-action:none; display:block}
.hud{position:absolute; top:0; left:0; right:0; padding:calc(env(safe-area-inset-top,0px) + 10px) 12px 0; display:flex; justify-content:space-between; align-items:flex-start; pointer-events:none; gap:8px}
.box{background:var(--chip); border:1px solid var(--line); border-radius:14px; padding:7px 12px}
.big{font-weight:900; font-size:28px; line-height:1}
.big.bump{animation:bump .45s ease}
@keyframes bump{30%{transform:scale(1.25)}}
.box small{display:block; font-size:12px; color:var(--soft); margin-top:3px}
.center{display:flex; flex-direction:column; align-items:center; gap:6px}
.hud .center{position:absolute; left:var(--netx,50%); top:calc(env(safe-area-inset-top,0px) + 10px); transform:translateX(-50%)} /* 12.49: centro na rede da mesa, não no meio da faixa do HUD */
.rally{background:rgba(255,210,94,.95); color:#2a2010; font-weight:900; font-size:15px; border-radius:999px; padding:5px 12px; opacity:0; transition:opacity .2s}
.rally.on{opacity:1}
.msg{position:absolute; left:50%; top:26%; transform:translate(-50%,-50%); font-weight:900; font-size:38px; pointer-events:none; opacity:0; text-shadow:0 4px 18px rgba(0,0,0,.5); white-space:nowrap}
.msg.on{animation:pop .9s ease-out forwards}
@keyframes pop{0%{opacity:0; transform:translate(-50%,-30%) scale(.6)} 15%{opacity:1; transform:translate(-50%,-50%) scale(1.12)} 30%{transform:translate(-50%,-50%) scale(1)} 100%{opacity:0; transform:translate(-50%,-90%)}}
.hint{position:absolute; left:50%; bottom:calc(env(safe-area-inset-bottom,0px) + 44px); transform:translateX(-50%); background:rgba(255,210,94,.95); color:#2a2010; font-weight:900; font-size:15px; padding:9px 16px; border-radius:999px; pointer-events:none; opacity:0; transition:opacity .2s; white-space:nowrap}
.hint.on{opacity:1}
.overlay{position:absolute; inset:0; display:grid; place-items:center; padding:12px; background:rgba(8,18,32,.74)} /* 12.79: sem desfoque (pesado no celular) */
.overlay.hidden{display:none}
.card{background:#16304d; border:1px solid var(--line); border-radius:20px; padding:16px 20px 14px; width:min(96%,640px); max-height:96%; overflow-y:auto}
.card h1{margin:0 0 4px; font-size:26px; font-weight:900}
.card h2{margin:10px 0 4px; font-size:14px; font-weight:900; color:var(--soft); text-transform:uppercase; letter-spacing:.06em}
.card p{color:var(--soft); line-height:1.45; font-size:14px; margin:4px 0}
.row{display:flex; gap:8px}
.row button{flex:1}
button{font:inherit; font-weight:900; font-size:16px; color:#fff; background:var(--accent); border:0; border-radius:999px; padding:11px 14px; width:100%; margin-top:6px; cursor:pointer; pointer-events:auto}
button.sec{background:transparent; border:1px solid var(--line); font-size:15px}
button.blue{background:#2b6fd8} button.green{background:#2f9a5a} button.purple{background:#7a4fd0}
button:focus-visible{outline:3px solid var(--gold); outline-offset:2px}
.fsBtn{width:auto; margin:0; font-size:13px; padding:8px 12px; background:var(--chip); border:1px solid var(--line)}
.stats{display:grid; grid-template-columns:1fr 1fr; gap:6px 14px; margin:8px 0 4px; font-size:14px; color:var(--soft)}
.stats b{color:var(--ink)}
.ladder{display:flex; flex-direction:column; gap:4px; margin:6px 0}
.ladder div{display:flex; justify-content:space-between; align-items:center; gap:10px; padding:4px 12px; border-radius:10px; background:rgba(255,255,255,.05); font-size:13px; line-height:1.25}
.ladder div.cur{outline:2px solid var(--gold)} .ladder div.won{opacity:.6}
.ladder small{color:var(--soft)}
.hidden{display:none !important}
.setRow{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:6px 0; border-bottom:1px solid var(--line)}
.setRow>span{font-weight:700; font-size:14px; white-space:nowrap}
.seg{display:flex; gap:6px; flex:1; max-width:340px}
.seg button{margin:0; padding:7px 8px; font-size:13px; background:transparent; border:1px solid var(--line)}
.seg.wrap{flex-wrap:wrap; max-width:420px; gap:6px} .overlay .seg.wrap button{flex:0 0 calc(25% - 5px) !important; width:calc(25% - 5px) !important; min-width:0 !important; padding:6px 2px !important; font-size:12px !important; margin:0 0 4px !important} /* 13.93: linha com muitas opções (Som do smash) quebra em várias */
.seg button[aria-pressed="true"]{background:var(--accent); border-color:transparent}
/* tutorial: faixa compacta embaixo, sobre o piso (fora da área de jogo) */
.tut{position:absolute; left:50%; bottom:calc(env(safe-area-inset-bottom,0px) + 8px); transform:translateX(-50%); display:flex; align-items:center; gap:10px; background:rgba(16,40,66,.85); border:1px solid rgba(255,210,94,.7); border-radius:999px; padding:5px 6px 5px 14px; max-width:92%; pointer-events:none; white-space:nowrap}
.tut small{color:var(--gold); font-weight:900; font-size:11px; letter-spacing:.05em; text-transform:uppercase}
.tut div{font-weight:900; font-size:14px; overflow:hidden; text-overflow:ellipsis}
.tut button{font-size:12px; padding:6px 10px}
.wallet{display:flex; align-items:center; gap:14px; margin-bottom:6px; font-size:14px}
.wallet .coin{background:rgba(255,210,94,.15); border:1px solid rgba(255,210,94,.5); border-radius:999px; padding:4px 10px}
.wallet .rank{display:flex; align-items:center; gap:8px; flex:1; flex-wrap:wrap}
.wallet small{color:var(--soft); font-size:12px}
.xpbar{display:inline-block; width:90px; height:7px; border-radius:4px; background:rgba(255,255,255,.12); overflow:hidden} .xpbar i{display:block; height:100%; background:var(--gold)}
.reward{font-weight:900; color:var(--gold); font-size:16px}
/* 11.7: recibo de moedas */
#end h1{margin:0 0 2px} #endScore{font-size:36px !important; margin:0 !important; line-height:1.05} #endText{margin:2px 0 4px; font-size:14px}
#end .stats{grid-template-columns:repeat(3,1fr); font-size:12.5px; margin:4px 0 2px; gap:2px 10px}
.rcpt{margin:2px auto 2px; max-width:320px; color:var(--ink,#f4f7fb); font-weight:700}
.rcpt .rLine{display:flex; justify-content:space-between; gap:12px; font-size:13px; padding:1px 4px; opacity:0; transform:translateX(-14px); transition:opacity .25s, transform .3s cubic-bezier(.2,.9,.3,1)}
.rcpt .rLine.in{opacity:.92; transform:none}
.rcpt.many{max-width:520px} .rcpt.many .rLines{display:grid; grid-template-columns:1fr 1fr; column-gap:22px}
.rcpt .rLine b{color:var(--gold,#ffd25e)}
.rcpt .rLine.old b{opacity:.75}
.rcpt .rTotal{display:flex; align-items:center; justify-content:center; gap:8px; margin:2px 0 0; font-size:26px; font-weight:900; color:var(--gold,#ffd25e)}
.rcpt .rTotal .rCoin{display:inline-block; font-size:26px}
.rcpt .rTotal .rCoin.hop{animation:rHop .14s ease-out}
.rcpt .rTotal .rNum.boing{animation:rBoing .45s cubic-bezier(.2,1.6,.4,1)}
@keyframes rHop{50%{transform:translateY(-5px) rotate(-10deg)}}
@keyframes rBoing{0%{transform:scale(1)} 40%{transform:scale(1.35)} 100%{transform:scale(1)}}
.rcpt .rXp{display:flex; align-items:center; gap:8px; justify-content:center; font-size:13px; margin-top:2px; opacity:0; transition:opacity .3s}
.rcpt .rXp.in{opacity:1}
.rcpt .rBar{position:relative; display:inline-block; width:150px; height:9px; border-radius:5px; background:rgba(255,255,255,.14); overflow:hidden}
.rcpt .rBar i{position:absolute; left:0; top:0; bottom:0; width:0; border-radius:5px; background:linear-gradient(90deg,#7be08a,#b6f08a)}
.rcpt .rBar.flash{animation:rFlash .5s ease-out}
@keyframes rFlash{40%{box-shadow:0 0 0 3px #ffd25e, 0 0 16px #ffd25e}}
.rcpt .rUp{margin-top:2px; font-size:15px; min-height:0; font-weight:900; color:#b6f08a; opacity:0; transform:scale(.8); transition:opacity .3s, transform .4s cubic-bezier(.2,1.6,.4,1)}
.rcpt .rUp.in{opacity:1; transform:none}
.coinSpray{position:absolute; z-index:30; pointer-events:none; font-size:18px; animation:cSpray .85s cubic-bezier(.2,.7,.4,1) forwards}
@keyframes cSpray{0%{transform:translate(-50%,-50%) scale(.6); opacity:1} 100%{transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(1) rotate(var(--r)); opacity:0}}
#wallet .coin.arrive b{color:#b6f08a}
#ladder > div.cur{cursor:pointer; transition:transform .12s} #ladder > div.cur:active{transform:scale(.98)} /* 12.48 */
#giftSpot{z-index:2} /* 12.34: o presente fica por cima do gato e do caixote quando se encostam */
#wallet .coin.hop{display:inline-block; animation:rHop .14s ease-out}
@media (prefers-reduced-motion:reduce){ .rcpt .rLine,.rcpt .rUp{transition:none} .coinSpray{display:none} }
.tabs{display:flex; gap:6px; margin:6px 0 8px; overflow-x:auto}
.tabs button{margin:0; width:auto; flex:1; padding:7px 10px; font-size:13px; background:transparent; border:1px solid var(--line)}
.tabs button[aria-pressed="true"]{background:var(--accent); border-color:transparent}
.sGrid{display:grid; grid-template-columns:repeat(auto-fill,minmax(112px,1fr)); gap:8px}
#q_gato.locked{filter:grayscale(.75) brightness(.8)} .sItem.spotLit{outline:3px solid #ffd25e!important; outline-offset:2px; animation:litPulse 1.1s ease-in-out 4} @keyframes litPulse{50%{outline-color:rgba(255,210,94,.35)!important}}
#shopMsg.pin{position:fixed; left:50%; bottom:14px; transform:translateX(-50%); z-index:9; max-width:90vw; box-shadow:0 4px 0 rgba(0,0,0,.35)}
.sItem{position:relative; background:rgba(255,255,255,.05); border:1px solid var(--line); border-radius:14px; padding:8px; display:flex; flex-direction:column; align-items:center; gap:4px; font-size:13px; text-align:center}
.sItem.eq{outline:2px solid var(--gold)}
.sItem button{font-size:13px; padding:7px 8px; margin-top:2px}
.sItem button.poor{background:#5a4038}
.sItem .tag{position:absolute; top:-8px; right:6px; background:var(--gold); color:#2a2010; font-weight:900; font-size:10px; border-radius:999px; padding:2px 7px}
.pv{width:64px; height:48px; display:grid; place-items:center}
.pv.charm{position:relative; width:64px; height:52px; background:linear-gradient(#d99a55,#b87a3a) no-repeat center 2px/34px 6px; border-radius:2px} .pv.charm svg{width:40px; height:48px; margin-top:4px; transform-origin:50% 0; animation:chSwing var(--d,2.2s) ease-in-out infinite} .pv.charm.none{background:none} .pv.charm span{font-size:12px; opacity:.6} /* 12.38: pingente balançando na loja */
@keyframes chSwing{0%,100%{transform:rotate(-16deg)}50%{transform:rotate(16deg)}}
.pv.paddle{width:24px; height:46px; border-radius:50%; background:var(--c); transform:rotate(-22deg); border:2px solid rgba(0,0,0,.35)}
.pv.paddle.neon{box-shadow:0 0 14px var(--c)} .pv.paddle.gold{background:linear-gradient(135deg,#fff0a8,var(--c),#a8740c)}
.pv.paddle.stripe{background:repeating-linear-gradient(35deg,var(--c) 0 6px,rgba(255,255,255,.8) 6px 9px)}
.pv3d{height:48px; width:auto; transform:rotate(-22deg)} .pv3d.neon{filter:drop-shadow(0 0 6px var(--c))} /* 13.25: raquete 3D na loja */
.pv.paddle.carbon{background:repeating-linear-gradient(45deg,#2a2d33 0 3px,#3a3e46 3px 5px),#2a2d33}
.pv.ball{width:18px; height:18px; border-radius:50%; background:var(--c)} .pv.ball.neon{box-shadow:0 0 12px var(--c)}
.pv.ball.fire{box-shadow:-14px 0 10px rgba(255,120,40,.8)} .pv.ball.gold{box-shadow:-14px 0 10px rgba(255,215,90,.8)}
.pv.table{width:64px; height:10px; border-radius:3px; background:var(--c); border-top:2px solid #f4f7fb}
.pv.scene{width:96px; height:52px; border-radius:8px; border:1px solid var(--line)}
.pv.coinpv{font-size:30px}
.note{font-size:12px; grid-column:1/-1}
.testAdd{grid-column:1/-1; display:flex; gap:8px; align-items:center; flex-wrap:wrap; padding:10px 12px; border:2px dashed rgba(255,214,110,.6); border-radius:14px; background:rgba(0,0,0,.18)} .testAdd b{flex:1 1 100%; font-size:13px} .testAdd input{flex:1; min-width:110px; font:inherit; font-size:16px; padding:8px 10px; border-radius:10px; border:2px solid rgba(255,255,255,.35); background:rgba(0,0,0,.25); color:#fff} .testAdd button{flex:0 0 auto; width:auto!important; margin:0!important; padding:8px 20px} /* 12.94: teste */
.toast{min-height:0; font-weight:900; color:var(--gold); text-align:center; opacity:0; transition:opacity .2s; pointer-events:none; font-size:14px; margin-top:4px; background:rgba(16,40,66,.92); border-radius:999px; padding:6px 12px}
.toast.on{opacity:1}
#start .card button{padding:9px 12px; margin-top:5px} #start .card h1{font-size:22px; margin:0} #start .card h2{margin:6px 0 2px}
.logo{display:flex; align-items:center; gap:8px; font-family:'Lilita One',Archivo,sans-serif; line-height:1}
.logoEmb{width:50px; height:50px; flex:none; filter:drop-shadow(0 3px 0 #0d2b59)}
.logoTxt{display:flex; flex-direction:column; align-items:flex-start}
.logoTxt b{font-weight:400; font-size:30px; letter-spacing:.5px; color:#ffc94a; text-shadow:1.0px 0.0px 0 #664800,0.92px 0.38px 0 #664800,0.71px 0.71px 0 #664800,0.38px 0.92px 0 #664800,0.0px 1.0px 0 #664800,-0.38px 0.92px 0 #664800,-0.71px 0.71px 0 #664800,-0.92px 0.38px 0 #664800,-1.0px 0.0px 0 #664800,-0.92px -0.38px 0 #664800,-0.71px -0.71px 0 #664800,-0.38px -0.92px 0 #664800,-0.0px -1.0px 0 #664800,0.38px -0.92px 0 #664800,0.71px -0.71px 0 #664800,0.92px -0.38px 0 #664800,0 3px 0 #664800; transform:rotate(-2deg)}
.logoTxt i{font-style:normal; font-size:15px; letter-spacing:3px; color:#fff; background:#ff7a3d; border:1.8px solid #662000; border-radius:8px; padding:2px 9px 1px; margin:3px 0 0 18px; box-shadow:0 3px 0 #662000; transform:rotate(-2deg)}
.ui-cozy .logoTxt b{color:#f2c46d} .ui-cozy .logoTxt i{background:#c8704a}
.menuTop{display:flex; align-items:center; gap:14px; flex-wrap:wrap} .menuTop .wallet{margin:0; flex:1; justify-content:flex-end}
/* cartas na partida: saem de baixo da tela, só a metade de cima aparece; as suas à direita do centro, as do adversário à esquerda */
.mcards{position:absolute; bottom:calc(env(safe-area-inset-bottom,0px) - 25px); right:calc(50% + 14px); display:flex; flex-direction:row-reverse; gap:7px; pointer-events:none} /* 12.33: cartas 15% maiores */
.mcards.mine{right:auto; left:calc(50% + 14px); flex-direction:row}
.mc{position:relative; width:44px; height:55px; margin:0; padding:5px 2px 0; border-radius:8px 8px 0 0; background:rgba(12,24,40,.72); border:1px solid rgba(255,255,255,.14); border-top:2px solid var(--tc); display:flex; flex-direction:column; align-items:center; justify-content:flex-start; gap:1px; font:inherit; font-size:8.6px; font-weight:800; color:rgba(244,247,251,.75); line-height:1.05; pointer-events:none; transition:transform .25s, opacity .3s}
.mc svg{width:20px; height:20px; flex:none; opacity:.85}
.mc span{display:none}
.mc i{position:absolute; top:-12px; left:50%; transform:translateX(-50%); font-style:normal; font-size:8px; font-weight:800; color:rgba(244,247,251,.7); white-space:nowrap}
.mc.pas{opacity:.7}
.mc[data-act]{pointer-events:auto; cursor:pointer; animation:cardBreath 2.4s ease-in-out infinite}
@keyframes cardBreath{50%{transform:translateY(-3px)}}
.mc.armed{transform:translateY(-6px); border-color:rgba(255,255,255,.3); border-top-color:var(--tc)}
.mc.active{transform:translateY(-8px); background:rgba(12,24,40,.85)}
.mc.used{opacity:.25} .mCost{display:block; margin:4px 0; padding:3px 8px; border-radius:8px; background:rgba(255,90,90,.18); color:#ffb3b3; font:800 11.5px Archivo,sans-serif} /* 15.58 */
.mc .uses{position:absolute; top:-7px; right:-7px; min-width:17px; height:17px; padding:0 3px; box-sizing:border-box; border-radius:9px; background:#fff3dc; color:#2a1a2e; border:1.5px solid #2a1a2e; font:400 11px/14px 'Lilita One',Archivo,sans-serif; text-align:center; box-shadow:0 1.5px 0 rgba(0,0,0,.35)} /* 12.33: usos que restam da passiva */
.mc.out{opacity:1; filter:none; border-top-color:rgba(200,200,210,.35)!important} .mc.out svg{opacity:.28; filter:grayscale(1)} .mc.out .uses{background:#c9c2bb} .mc .uses.cd{min-width:26px; font-size:11px; background:#fff3dc; color:#2a1a2e; border-color:#2a1a2e} /* 12.43: segundos de recarga */
/* quando o aviso fixo de saque está na tela, a mensagem do rodapé sobe para ficar logo acima dele */
#lockMsg{transition:opacity .2s, bottom .2s}
#hint.on ~ #lockMsg{bottom:calc(env(safe-area-inset-bottom,0px) + 92px) !important}
/* janelas (menu, loja...) sempre acima das cartas e avisos da partida; a mensagem do rodapé fica acima de tudo */
.overlay{z-index:5} #lockMsg{z-index:6}
/* tela de preparação antes de cada partida do torneio */
.pmHead{display:flex; align-items:center; gap:10px} .pmHead .dot{width:16px; height:16px; flex:none} .pmHead h1{margin:0}
.pmHead small{display:block; color:var(--soft); font-size:12px; margin-top:2px}
#setSheet .card{padding-bottom:10px} .ssHead{display:flex; align-items:center; justify-content:space-between; gap:10px} .ssHead small{opacity:.8; font-weight:800; letter-spacing:.04em} .ssHead h1{margin:0}
.ssScore{display:flex; align-items:center; gap:8px; font:900 26px/1 'Lilita One',system-ui,sans-serif; padding:6px 14px; border-radius:14px; background:rgba(0,0,0,.22)} .ssScore i{width:12px; height:12px; border-radius:50%; background:rgba(255,255,255,.18); display:inline-block} .ssScore i.on{background:#7be08a} .ssScore i.onL{background:#ff8f6b}
.ssChange{font-size:13px; margin:2px 0 4px; font-weight:700} .ssChange.mudou{color:#ffd25e} .ssChange.igual{opacity:.8}
#ssOpp .tcard{transform:scale(.8); transform-origin:left top; margin:0 -10px -22px 0; position:relative} #ssOpp .tcard.nova::after{content:'NOVA'; position:absolute; top:-6px; right:-6px; background:#ffd25e; color:#3a2a08; font:900 9px/1 system-ui,sans-serif; padding:3px 5px; border-radius:6px} #ssOpp .tcard.saiu{opacity:.35; filter:grayscale(1)} #ssOpp .tcard.saiu::after{content:'SAIU'; position:absolute; top:-6px; right:-6px; background:#8a8f98; color:#fff; font:900 9px/1 system-ui,sans-serif; padding:3px 5px; border-radius:6px}
#ssSlots{margin:2px 0 8px} #ssGo{width:100%} /* 12.98: tela entre os sets */
.pmCards{display:flex; gap:8px; flex-wrap:wrap; margin:2px 0 4px} .pmCards .tcard{width:60px; height:78px; font-size:10px; gap:2px} .pmCards .tcard svg{width:28px; height:28px} .pmCards .tcard small{font-size:8px}
#pmSlots{margin:2px 0 6px}

/* ===================== ESTILO DOS MENUS (protótipo 6.8) =====================
   "Vivo": fiel à referência de jogo mobile casual (cores saturadas, contorno azul-marinho).
   "Aconchegante": mesma estrutura (contorno grosso, degrau embaixo, faixa de brilho em cima), cores quentes e menos saturadas.
   Só os menus (.overlay) mudam; a partida fica como está. Fonte Lilita One (OFL) embutida para funcionar sem internet. */
@font-face{font-family:'Lilita One'; src:url(data:font/ttf;base64,) format('truetype'); font-display:swap}
.ui-vivo{ --ol:#142039; --panel1:#2f5aa8; --panel2:#24468a; --tile:#1d3b78; --pill:#10203f; --txt:#ffffff; --soft2:#cfe0ff;
  --c-or:#ff8a1f; --h-or:#ffb54d; --l-or:#c9520a;  --c-bl:#2fa8ff; --h-bl:#7dd3ff; --l-bl:#1662c4;  --c-pu:#a446e6; --h-pu:#cf85ff; --l-pu:#6a20a8;
  --c-gr:#4fcf1f; --h-gr:#93ee44; --l-gr:#2c8f12;  --c-rd:#e8433a; --h-rd:#ff8a80; --l-rd:#9e1f1a;  --c-se:#3a5590; --h-se:#5876b8; --l-se:#22356a;  --o-or:#663100; --o-bl:#003b66; --o-pu:#3b0660; --o-gr:#1f5e08; --o-rd:#610905; --o-se:#1a2a4c; }
