.hubCol{position:absolute; top:66px; display:grid; grid-template-columns:repeat(2,96px); gap:12px 12px; pointer-events:none}
.hubL{left:calc(env(safe-area-inset-left,0px) + 16px)} .hubR{right:calc(env(safe-area-inset-right,0px) + 16px)}
#hub button.hubB{pointer-events:auto; position:relative; width:96px; height:96px; margin:0; padding:6px 4px 4px; border-radius:20px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; font-size:14px; line-height:1}
