#hub button.hubB em{position:absolute; top:-6px; right:-6px; min-width:24px; height:24px; padding:0 4px; box-sizing:border-box; border-radius:12px; background:#e5382f; color:#fff; font:800 15px/22px 'Baloo 2',sans-serif; text-shadow:none; border:2px solid #fff; box-shadow:0 2px 0 rgba(60,10,10,.45); display:none}
