@keyframes emPop{0%{transform:scale(0)}70%{transform:scale(1.25)}100%{transform:scale(1)}}
/* 13.66: telefone tocando de verdade: rajadas de tremida (trrrim… pausa… trrrim) e ondas de som saindo do aparelho */
#hub button.hubB.ring{animation:hubRing 1.6s infinite}
#hub button.hubB.ring i{animation:hubRingI 1.6s infinite; transform-origin:50% 60%}
#hub button.hubB.ring::before, #hub button.hubB.ring::after{content:''; position:absolute; left:50%; top:30px; width:44px; height:44px; margin:-22px 0 0 -22px; border-radius:50%; border:3px solid rgba(255,255,255,.85); border-left-color:transparent; border-right-color:transparent; pointer-events:none; animation:hubWave 1.6s ease-out infinite}
#hub button.hubB.ring::after{animation-delay:.25s}
@keyframes hubRing{0%,45%,100%{transform:translate(0,0) rotate(0)} 3%{transform:translate(-2px,0) rotate(-4deg)} 6%{transform:translate(2px,0) rotate(4deg)} 9%{transform:translate(-2px,0) rotate(-4deg)} 12%{transform:translate(2px,0) rotate(4deg)} 15%{transform:translate(-2px,0) rotate(-3deg)} 18%{transform:translate(2px,0) rotate(3deg)} 21%{transform:translate(-1px,0) rotate(-2deg)} 24%{transform:translate(1px,0) rotate(2deg)} 27%{transform:translate(0,0) rotate(0)}}
@keyframes hubRingI{0%,45%,100%{transform:rotate(0) scale(1)} 4%{transform:rotate(-18deg) scale(1.12)} 8%{transform:rotate(18deg) scale(1.12)} 12%{transform:rotate(-18deg) scale(1.12)} 16%{transform:rotate(18deg) scale(1.12)} 20%{transform:rotate(-12deg) scale(1.08)} 24%{transform:rotate(12deg) scale(1.05)} 28%{transform:rotate(0) scale(1)}}
@keyframes hubWave{0%{transform:scale(.6); opacity:0} 10%{opacity:1} 40%{transform:scale(1.9); opacity:0} 100%{transform:scale(1.9); opacity:0}}
/* botão com algo para pegar: uma sacudida curta a cada 3 s */
#hub button.hubB.nudge{animation:hubNudge 3s infinite}
@keyframes hubNudge{0%,12%,100%{transform:rotate(0)} 2%{transform:rotate(-6deg)} 4%{transform:rotate(6deg)} 6%{transform:rotate(-5deg)} 8%{transform:rotate(4deg)} 10%{transform:rotate(-2deg)}}
#hub button.hubB.off{display:none}
