/* 14.75 (dono): o alçapão do menu mostra a luz roxa saindo do chão (frestas acesas e brilho subindo, pulsando), para o balão "Que luz roxa é essa?" fazer sentido */
#hub button.hubTrap{width:52px; height:38px; opacity:1; overflow:visible; background:linear-gradient(#3a2a1c,#2a1d12) !important; border:2.5px solid #120c16 !important; box-shadow:0 3px 0 #120c16, 0 0 14px 2px rgba(178,92,255,.55) !important; animation:trapGlow 1.8s ease-in-out infinite; font-size:0}
