.ecCard .ecPlus{position:absolute; right:-6px; top:-7px; width:16px; height:16px; border-radius:50%; background:#3fbf5a; border:2px solid #3a2616; color:#fff; font:900 13px/12px system-ui,sans-serif; text-align:center; animation:ecPlus .6s cubic-bezier(.2,.9,.3,1.6) .25s both}
.ecFly{position:absolute; left:20px; top:-2px; font-size:11px; color:#3fbf5a; animation:ecFly 1.4s ease-out .4s both; pointer-events:none}
@keyframes ecWig{25%{transform:rotate(-10deg)} 75%{transform:rotate(10deg)}}
@keyframes ecPlus{0%{transform:scale(0) rotate(-90deg)} 100%{transform:scale(1) rotate(0)}}
@keyframes ecFly{0%{opacity:0; transform:translate(0,0) scale(.6)} 20%{opacity:1} 100%{opacity:0; transform:translate(10px,-18px) scale(1.2)}}
