.ctToast{position:fixed; z-index:60; left:50%; top:14px; transform:translate(-50%,-140%); display:flex; align-items:center; gap:12px; padding:10px 18px 10px 12px; border-radius:16px; background:#fff6e6; color:#3a2616; border:2.5px solid #3a2616; box-shadow:0 5px 0 rgba(0,0,0,.35); pointer-events:none; transition:transform .45s cubic-bezier(.2,.9,.3,1.25), opacity .4s; max-width:min(440px,90vw)}
.ctToast.on{transform:translate(-50%,0)} .ctToast.out{transform:translate(-50%,-140%); opacity:0}
.ctToast .ctIc{font-size:28px; animation:ctRing .5s ease-in-out 3} .ctToast small{display:block; font-size:11px; font-weight:900; letter-spacing:.06em; text-transform:uppercase; color:#3fbf5a} .ctToast b{display:flex; align-items:center; gap:7px; font-size:17px} .ctToast b i{width:12px; height:12px; border-radius:50%; border:2px solid #3a2616} .ctToast em{display:block; font-style:normal; font-size:13px; font-weight:700; opacity:.8}
