.agBody .agRow button{flex:none; width:auto !important; min-width:0 !important; margin:0 !important; padding:7px 14px !important; font-size:14px !important} .agEmpty{opacity:.8; text-align:center; padding:18px 8px}
.agBody::-webkit-scrollbar{display:none} .agBar{position:absolute; right:0; top:4px; bottom:4px; width:8px; touch-action:none; border-radius:8px; background:rgba(255,255,255,.14)} .agBar::before{content:''; position:absolute; left:-12px; right:-6px; top:0; bottom:0} .agBar.hidden{display:none} .agBar i{position:absolute; left:0; right:0; top:0; min-height:24px; border-radius:8px; background:#ffd25e; border:1px solid rgba(0,0,0,.35); box-sizing:border-box} /* 13.06: barra própria (a do Android some sozinha) */
.agMore{position:absolute; left:0; right:18px; bottom:0; padding:18px 0 4px; text-align:center; font-weight:900; font-size:13px; color:#ffd25e; pointer-events:none; background:linear-gradient(rgba(37,74,150,0),rgba(37,74,150,.95) 60%); border-radius:0 0 12px 12px; animation:agBob 1.2s ease-in-out infinite} .agMore.hidden{display:none}
