.chRow{display:flex; align-items:center; gap:10px; padding:6px 8px; margin-bottom:6px; border-radius:10px; background:rgba(0,0,0,.18)} .chRow.ok{background:rgba(123,224,138,.18); box-shadow:inset 0 0 0 2px rgba(123,224,138,.55)} .chRow.got{opacity:.55}
