/* 12.57: comemoração de campeão */
#champFx{position:fixed; inset:0; z-index:30; overflow:hidden; background:rgba(8,6,20,0); transition:background .5s, opacity .4s; font-family:'Lilita One',Archivo,sans-serif; cursor:pointer}
#champFx.on{background:rgba(8,6,20,.84)} #champFx.out{opacity:0}
#champFx .cfx{position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:3}
#champFx .cSpot{position:absolute; left:50%; top:0; width:min(70vw,520px); height:100%; transform:translate(-50%,-100%); background:radial-gradient(ellipse 60% 70% at 50% 0%,rgba(255,236,170,.42),rgba(255,236,170,.12) 55%,transparent 75%); clip-path:polygon(38% 0,62% 0,100% 100%,0 100%); transition:transform .7s cubic-bezier(.2,.8,.3,1)}
#champFx.on .cSpot{transform:translate(-50%,0)}
#champFx .cCup{position:absolute; left:50%; top:52%; width:min(27vh,130px); transform:translate(-50%,-160vh); z-index:2; filter:drop-shadow(0 8px 18px rgba(0,0,0,.5)) drop-shadow(0 0 28px rgba(255,214,110,.45))}
#champFx .cCup svg{display:block; width:100%; height:auto}
#champFx.drop .cCup{animation:cupDrop .6s cubic-bezier(.5,0,1,1) forwards}
#champFx.land .cCup{animation:cupLand .7s cubic-bezier(.2,1.6,.4,1) forwards}
#champFx.spin .cCup svg{animation:cupSpin 1.1s ease-in-out}
@keyframes cupDrop{to{transform:translate(-50%,-50%)}}
@keyframes cupLand{0%{transform:translate(-50%,-50%) scale(1.15,.82)} 45%{transform:translate(-50%,-62%) scale(.95,1.06)} 100%{transform:translate(-50%,-50%) scale(1)}}
@keyframes cupSpin{0%{transform:rotateY(0)} 100%{transform:rotateY(360deg)}}
#champFx .cShine{position:absolute; inset:0; background:linear-gradient(115deg,transparent 35%,rgba(255,255,255,.75) 48%,transparent 60%); background-size:250% 100%; background-position:120% 0; mix-blend-mode:overlay; -webkit-mask:linear-gradient(#000,#000); pointer-events:none}
#champFx.spin .cShine{animation:cupShine 1.2s .9s ease-in-out}
@keyframes cupShine{to{background-position:-60% 0}}
#champFx .cBan{position:absolute; left:50%; top:6%; transform:translate(-50%,0) scale(0); z-index:4; text-align:center; white-space:nowrap}
#champFx .cBan b{display:block; font-size:clamp(40px,7.4vw,70px); line-height:1; color:#ffd25e; -webkit-text-stroke:10px #5a3a08; paint-order:stroke fill; text-shadow:0 5px 0 #5a3a08,0 0 34px rgba(255,210,94,.55); letter-spacing:.03em}
#champFx .cBan span{display:inline-block; margin-top:6px; padding:4px 18px; border-radius:6px; background:var(--lc); color:#fff; font-size:clamp(14px,2.3vw,20px); letter-spacing:.04em; box-shadow:0 3px 0 rgba(0,0,0,.35); -webkit-text-stroke:0}
#champFx.ban .cBan{animation:banPop .65s cubic-bezier(.2,1.7,.4,1) forwards}
@keyframes banPop{to{transform:translate(-50%,0) scale(1)}}
#champFx .cRow{position:absolute; left:50%; bottom:5%; transform:translate(-50%,140%); display:flex; gap:clamp(8px,2.2vw,22px); z-index:4; transition:transform .6s cubic-bezier(.2,1.3,.4,1)}
#champFx.row .cRow{transform:translate(-50%,0)}
#champFx .cFace{position:relative; display:flex; flex-direction:column; align-items:center; width:clamp(44px,8vw,62px)}
#champFx .cFace svg{width:100%; height:auto; background:#fff6e6; padding:3px; border-radius:6px; box-shadow:0 3px 0 rgba(0,0,0,.35)}
#champFx .cFace small{font-family:Archivo,sans-serif; font-weight:700; color:#fff; font-size:11px; margin-top:3px; white-space:nowrap}
#champFx .cFace em{position:absolute; top:-14px; right:-8px; font-style:normal; font-size:16px; opacity:0}
#champFx.row .cFace{animation:clap .42s var(--d) ease-in-out 6 alternate}
#champFx.row .cFace em{animation:clapE .42s var(--d) ease-in-out 6 alternate}
@keyframes clap{from{transform:translateY(0)} to{transform:translateY(-9px)}}
@keyframes clapE{from{opacity:0; transform:scale(.6)} to{opacity:1; transform:scale(1.15)}}
#champFx .cTap{position:absolute; right:14px; bottom:8px; z-index:4; color:rgba(255,255,255,.55); font:600 12px Archivo,sans-serif; opacity:0; transition:opacity .4s}
