/* 8.4: objetos maiores, ícones no lugar das etiquetas; o nome só aparece na 1ª visita, ao segurar o dedo ou depois de um tempo parado */
.spot span, .spot .badge{display:none} /* 8.5: sem nomes na tela (os ícones bastam; o nome fica só para leitor de tela, em aria-label) */
.spot .badge{position:absolute; left:50%; top:0; margin:-22px 0 0 -22px; width:44px; height:44px; border-radius:50%; display:grid; place-items:center; pointer-events:none;
  --c:var(--c-bl); --h:var(--h-bl); --o:var(--o-bl);
  background:radial-gradient(circle at 50% 28%, var(--h) 0 35%, var(--c) 72%); border:2px solid var(--o); box-shadow:inset 0 -3px 0 rgba(0,0,0,.18), 0 3px 0 var(--o), 0 6px 8px rgba(0,0,0,.35);
  animation:badgeBob 3.4s ease-in-out infinite}
.spot .badge svg{width:25px; height:25px; filter:drop-shadow(0 1.5px 0 rgba(0,0,0,.35))}
.spot[data-spot="tour"] .badge{--c:var(--c-pu); --h:var(--h-pu); --o:var(--o-pu); animation-delay:-.4s}
.spot[data-spot="shop"] .badge{--c:var(--c-gr); --h:var(--h-gr); --o:var(--o-gr); animation-delay:-1.1s}
.spot[data-spot="tech"] .badge{--c:var(--c-rd); --h:var(--h-rd); --o:var(--o-rd); animation-delay:-1.9s}
.spot[data-spot="radio"] .badge{--c:var(--c-se); --h:var(--h-se); --o:var(--o-se); animation-delay:-2.6s}
