@keyframes badgeBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
.spot:active .badge, .spot.bump .badge{animation:badgePop .3s ease-out}
@keyframes badgePop{0%{transform:scale(1)}40%{transform:scale(1.22)}100%{transform:scale(1)}}
.spot.bump{animation:none}
.roomTop .wallet .coin{cursor:pointer}
.spot .badge{display:none !important} /* 8.5: áreas tracejadas no lugar dos ícones */
