/* 12.8: multiplicador do rally: letreiro dourado grande que pula, separado do selo do rally */
.multPop{position:absolute; left:calc(50% + 20px); top:21%; transform:translate(-50%,-50%); pointer-events:none; text-align:center; opacity:0; z-index:4}
.multPop b{display:block; position:relative; font-family:'Lilita One',Archivo,sans-serif; font-weight:400; font-size:50px; line-height:1; letter-spacing:.03em; color:#ffcd45; -webkit-text-stroke:2.5px #ffcd45; paint-order:stroke fill} /* 12.10: letra mais gordinha (traço da própria cor) */
.multPop b::before{content:attr(data-t); position:absolute; inset:0; z-index:-1; color:#5a3300; -webkit-text-stroke:8px #5a3300; paint-order:stroke fill; transform:translateY(2px)} /* contorno marrom por trás */
.multPop.go{animation:multRise 2.2s ease-out both}
@keyframes multRise{0%{opacity:0; transform:translate(-50%,-30%)} 22%{opacity:1} 70%{opacity:1} 100%{opacity:0; transform:translate(-50%,-95%)}} /* 12.10: aparece, sobe devagar e some */
.rallyWrap{position:relative; display:inline-block}
.multBreak{position:absolute; left:var(--netx,50%); top:30%; width:150px; height:96px; transform:translate(-50%,-50%); pointer-events:none; z-index:6; animation:mbIn .45s cubic-bezier(.2,.9,.3,1.3) both} /* 12.53: multiplicador perdido racha */
.multBreak .mbH{position:absolute; inset:0 0 18px; display:grid; place-items:center; transition:transform .9s cubic-bezier(.5,0,.9,.5), opacity .9s}
.multBreak .mbH b{font-family:'Lilita One',Archivo,sans-serif; font-weight:400; font-size:66px; line-height:1; color:#ffcd45; -webkit-text-stroke:8px #5a3300; paint-order:stroke fill; text-shadow:0 3px 0 #5a3300}
.multBreak .mbH.l{clip-path:polygon(0 0,52% 0,46% 22%,56% 38%,44% 55%,54% 72%,47% 100%,0 100%)} .multBreak .mbH.r{clip-path:polygon(52% 0,100% 0,100% 100%,47% 100%,54% 72%,44% 55%,56% 38%,46% 22%)}
.multBreak .mbCrack{position:absolute; left:0; top:0; width:100%; height:calc(100% - 18px); opacity:0; stroke-dasharray:120; stroke-dashoffset:120}
.multBreak.crack .mbCrack{opacity:1; stroke-dashoffset:0; transition:stroke-dashoffset .22s ease-out} .multBreak.crack{animation:mbShake .2s linear}
.multBreak.fall .mbCrack{opacity:0; transition:opacity .2s} .multBreak.fall .mbH.l{transform:translate(-26px,70px) rotate(-24deg); opacity:0} .multBreak.fall .mbH.r{transform:translate(26px,74px) rotate(22deg); opacity:0}
.multBreak small{position:absolute; left:50%; bottom:-6px; transform:translateX(-50%); white-space:nowrap; font-family:'Lilita One',Archivo,sans-serif; font-size:15px; color:#ffb3a8; -webkit-text-stroke:4px #3a1410; paint-order:stroke fill; animation:mbCap 1.9s ease both}
@keyframes mbIn{0%{opacity:0; transform:translate(-50%,-50%) scale(.4)} 100%{opacity:1; transform:translate(-50%,-50%) scale(1)}}
@keyframes mbShake{25%{transform:translate(calc(-50% - 3px),-50%)} 75%{transform:translate(calc(-50% + 3px),-50%)}}
@keyframes mbCap{0%,30%{opacity:0} 45%,80%{opacity:1} 100%{opacity:0}}
.multChip{position:absolute; left:100%; top:-9px; margin-left:-16px; z-index:3; pointer-events:none; padding:1px 8px 2px; border-radius:999px; font-family:'Lilita One',Archivo,sans-serif; font-size:14px; line-height:1.2; color:#fff6e6; transform:rotate(-10deg); background:linear-gradient(180deg,#ff8a5c,#e8492f 60%,#c2321f); border:2px solid #4a1408; box-shadow:0 2px 0 #4a1408; -webkit-text-stroke:2.5px #4a1408; paint-order:stroke fill; opacity:0; transition:opacity .2s} /* 12.14: cor própria (coral), aparece e some com o selo do rally */
  background:linear-gradient(180deg,#fff0a0,#ffc93c 55%,#e9a01c); border:2.5px solid #5a3300; box-shadow:0 3px 0 #5a3300, 0 0 12px rgba(255,200,60,.45)}
.inRoom .multChip{display:none!important} .multChip.on{opacity:1} .multChip.bump{animation:chipBump .6s cubic-bezier(.2,.8,.3,1)}
@keyframes chipBump{0%{opacity:.3} 100%{opacity:1}}

/* 12.12: balão de fala do quarto (gato na expedição; depois o telefone). Fica acima do objeto que fala, com rabinho */
.roomTalk{position:absolute; z-index:7; width:max-content; max-width:min(300px,70vw); box-sizing:border-box; /* 13.14: largura própria; antes encolhia perto da borda direita e ficava alto demais */ transform:translate(-50%,-100%); pointer-events:auto; cursor:pointer}
.roomTalk.hidden{display:none}
/* 13.03: conversa no telefone: balões em sequência, nome de quem fala, toque para avançar, respostas */
.callBox{position:absolute; z-index:8; width:min(330px,74vw); transform:translate(-50%,-100%); padding:10px 16px 12px; border-radius:16px; background:#fff6e6; color:#3a2616; border:2.5px solid #3a2616; box-shadow:0 4px 0 rgba(0,0,0,.3); cursor:pointer}
.callBox.hidden{display:none}
.callBox.go{animation:rtIn .28s cubic-bezier(.2,.8,.3,1.2) both}
.callBox::after{content:''; position:absolute; left:var(--ax,67%); bottom:-9px; width:14px; height:14px; margin-left:-7px; background:#fff6e6; border-right:2.5px solid #3a2616; border-bottom:2.5px solid #3a2616; transform:rotate(45deg)}
.callBox .cbWho{display:flex; align-items:center; gap:7px; font-size:12px; font-weight:900; letter-spacing:.03em; text-transform:uppercase; margin-bottom:4px}
.callBox .cbWho i{width:12px; height:12px; border-radius:50%; border:2px solid #3a2616}
.callBox .cbWho span{margin-left:auto; margin-right:14px; font-size:13px}
.callBox .cbTxt{margin:0; font-weight:800; font-size:15px; line-height:1.3}
.callBox .cbNext{display:block; text-align:right; font-size:11px; font-weight:900; opacity:.55; margin-top:4px}
.callBox .cbNext.hidden{display:none}
.callBox .cbOpts{display:flex; gap:8px; margin-top:8px}
.callBox .cbOpts:empty{display:none}
.callBox .cbOpts button{flex:1; padding:8px 6px; border-radius:12px; font-weight:900; font-size:14px; border:2.5px solid #3a2616; box-shadow:0 3px 0 #3a2616; color:#fff6e6; background:#4fb33a; cursor:pointer}
.callBox .cbOpts .cbNo{background:#8a7a6a}
.roomTalk .rtTxt{margin:0; padding:12px 30px 12px 16px; border-radius:16px; background:#fff6e6; color:#3a2616; font-weight:800; font-size:14px; line-height:1.3; text-align:center; border:2.5px solid #3a2616; box-shadow:0 4px 0 rgba(0,0,0,.3)}
.roomTalk::after{content:''; position:absolute; left:calc(50% + var(--tx,0px)); bottom:-9px; width:14px; height:14px; margin-left:-7px; background:#fff6e6; border-right:2.5px solid #3a2616; border-bottom:2.5px solid #3a2616; transform:rotate(45deg)}
.roomTalk .rtX,.callBox .rtX{position:absolute; top:-11px; right:-11px; width:30px; height:30px; min-width:0 !important; min-height:0 !important; padding:0 !important; border-radius:50% !important; display:grid; place-items:center; font-size:15px !important; font-weight:900; line-height:1; color:#fff6e6 !important; background:#e8492f !important; border:2.5px solid #3a2616 !important; box-shadow:0 2px 0 #3a2616 !important}
.roomTalk.go{animation:rtIn .32s cubic-bezier(.2,.8,.3,1.2) both}
@keyframes rtIn{0%{opacity:0; transform:translate(-50%,-90%) scale(.85)} 100%{opacity:1; transform:translate(-50%,-100%) scale(1)}}

/* 12.13: tela de revelar o presente do gato */
#giftReveal{z-index:8; background:rgba(10,8,20,.72)}
.grWrap{position:relative; display:flex; flex-direction:column; align-items:center; text-align:center; width:min(360px,90vw)}
.grWrap h2{margin:6px 0 2px; font-family:'Lilita One',Archivo,sans-serif; font-weight:400; font-size:24px; color:#fff6e6; -webkit-text-stroke:5px #2a1d12; paint-order:stroke fill}
.grWrap p{margin:0 0 10px; color:#f3e6d2; font-weight:700; font-size:14px; min-height:1.3em}
.grGift{width:150px; height:150px; padding:0 !important; background:transparent !important; border:0 !important; box-shadow:none !important; cursor:pointer; animation:grIdle 1.8s ease-in-out infinite; transform-origin:50% 90%}
.grGift svg{width:100%; height:100%; overflow:visible}
@keyframes grIdle{0%,70%,100%{transform:rotate(0)} 76%{transform:rotate(-6deg)} 82%{transform:rotate(5deg)} 88%{transform:rotate(-3deg)} 94%{transform:rotate(2deg)}}
.grLid{transition:transform .5s cubic-bezier(.2,.8,.3,1.2), opacity .5s .2s; transform-origin:60px 40px}
.open .grGift{animation:none; cursor:default}
.open .grLid{transform:translate(18px,-70px) rotate(24deg); opacity:0}
.open .grBody{animation:grDrop .5s ease-out .1s both} @keyframes grDrop{to{transform:translateY(14px); opacity:.0}}
.grRays{position:absolute; left:50%; top:75px; width:260px; height:260px; margin:-130px 0 0 -130px; border-radius:50%; opacity:0; pointer-events:none;
  background:repeating-conic-gradient(rgba(255,214,110,.28) 0 10deg, transparent 10deg 24deg); -webkit-mask:radial-gradient(circle,#000 30%,transparent 70%); mask:radial-gradient(circle,#000 30%,transparent 70%)}
.open .grRays{animation:grRays 6s linear infinite, grFade .6s ease-out both} @keyframes grRays{to{transform:rotate(360deg)}} @keyframes grFade{from{opacity:0} to{opacity:1}}
.grItem{position:absolute; left:50%; top:75px; transform:translate(-50%,-50%) scale(0); display:grid; place-items:center; pointer-events:none}
.open .grItem{animation:grPop .7s cubic-bezier(.2,.8,.3,1.3) .25s both} @keyframes grPop{0%{transform:translate(-50%,-10%) scale(0)} 100%{transform:translate(-50%,-50%) scale(1)}}
.grItem .grCharm .pv.charm{transform:scale(1.6); transform-origin:50% 0; margin-bottom:40px} /* 12.96 */
.grItem .grBall{width:64px; height:64px; border-radius:50%; background:radial-gradient(circle at 35% 30%,#fff8 0 18%,transparent 19%),var(--c); border:4px solid #2a1d12; box-shadow:0 6px 0 rgba(0,0,0,.3)}
.grItem .grCoins{font-family:'Lilita One',Archivo,sans-serif; font-size:44px; color:#ffd84a; -webkit-text-stroke:6px #5a3300; paint-order:stroke fill}
.grBtns{opacity:0; pointer-events:none; transition:opacity .3s .8s} .open .grBtns{opacity:1; pointer-events:auto}

/* 12.22: recibo ensina a multiplicação: o total conta o valor real, aparece o ×2 ao lado e o número multiplica */
.rTotal{position:relative}
.rMult{display:inline-block; margin-left:8px; padding:1px 9px 3px; border-radius:999px; font-family:'Lilita One',Archivo,sans-serif; font-size:22px; line-height:1.1; color:#fff6e6; background:linear-gradient(180deg,#ff8a5c,#e8492f 60%,#c2321f); border:2.5px solid #4a1408; box-shadow:0 3px 0 #4a1408; -webkit-text-stroke:3px #4a1408; paint-order:stroke fill; transform:rotate(-8deg) scale(0); vertical-align:middle}
.rMult.in{animation:rMultIn .5s cubic-bezier(.2,.8,.3,1.4) both} @keyframes rMultIn{0%{transform:rotate(-8deg) scale(0)} 100%{transform:rotate(-8deg) scale(1)}}
.rMultCap{display:block; font-size:11px; font-weight:800; color:#ffb59c; opacity:0; transition:opacity .3s; margin-top:2px} .rMultCap.in{opacity:1}
/* 12.22: tutorial do multiplicador (primeira vez): câmera aproxima do selinho, quase parado, com balão */
#app{transition:transform 1.4s cubic-bezier(.4,0,.2,1)} /* 12.23: zoom lento e suave */
#tutTalk{position:fixed; z-index:30} #tutTalk.below{transform:translate(-50%,0)} #tutTalk.below.go{animation:rtInB .32s cubic-bezier(.2,.8,.3,1.2) both}
#pauseSheet{z-index:20} .pauseCard{max-width:380px; text-align:center} .pauseCard h1{margin-bottom:4px} .pauseCard .note{margin:0 0 14px} /* 12.53: pausa */
.pauseBtn{min-width:44px; font-size:16px; letter-spacing:-2px; pointer-events:auto}
#pauseCount{position:fixed; left:50%; top:45%; transform:translate(-50%,-50%); z-index:21; pointer-events:none; font-family:'Lilita One',Archivo,sans-serif; font-size:84px; color:#fff3dc; -webkit-text-stroke:9px #2a1a2e; paint-order:stroke fill}
#pauseCount.go{animation:pcPop .48s ease-out both} @keyframes pcPop{0%{opacity:0; transform:translate(-50%,-50%) scale(1.6)} 30%{opacity:1; transform:translate(-50%,-50%) scale(1)} 100%{opacity:.2; transform:translate(-50%,-50%) scale(.9)}}
#winBanner{position:fixed; left:50%; top:34%; z-index:7; pointer-events:none; white-space:nowrap; font-family:'Lilita One',Archivo,sans-serif; font-size:clamp(46px,8.5vw,78px); line-height:1; letter-spacing:.02em; transform:translate(-50%,-50%); opacity:0} /* 12.53: letreiro do fim da partida */
#winBanner.good{color:#8ff07a; -webkit-text-stroke:11px #17401a; paint-order:stroke fill; text-shadow:0 5px 0 #17401a, 0 0 30px rgba(143,240,122,.45)}
#winBanner.bad{color:#ff8a7a; -webkit-text-stroke:11px #4a1410; paint-order:stroke fill; text-shadow:0 5px 0 #4a1410, 0 0 30px rgba(255,120,100,.4)}
#winBanner.go{animation:wbIn .7s cubic-bezier(.2,1.4,.4,1) both} #winBanner.out{animation:wbOut .5s ease-in both}
@keyframes wbIn{0%{opacity:0; transform:translate(-50%,-50%) scale(2.2) rotate(-6deg)} 60%{opacity:1; transform:translate(-50%,-50%) scale(.94) rotate(1deg)} 100%{opacity:1; transform:translate(-50%,-50%) scale(1) rotate(0)}}
@keyframes wbOut{0%{opacity:1; transform:translate(-50%,-50%) scale(1)} 100%{opacity:0; transform:translate(-50%,-140%) scale(.7)}}
#gest{position:absolute; width:170px; height:170px; z-index:4; pointer-events:none; transition:opacity .3s} #gest.dim{opacity:.3} /* 12.52: mãozinha do tutorial de efeito */
#gest .gTrail{position:absolute; inset:0; overflow:visible} #gest .gPath{fill:none; stroke:#ffd25e; stroke-width:7; stroke-linecap:round; stroke-dasharray:180; stroke-dashoffset:180; filter:drop-shadow(0 0 6px rgba(255,210,94,.6)); animation:gDraw 1.9s ease-in-out infinite}
#gest .gBall{fill:#fff6e6; stroke:#2a1a2e; stroke-width:2.2} #gest .gSpin{animation:gSpin 1.9s ease-in-out infinite; transform-box:fill-box}
@keyframes gDraw{0%{stroke-dashoffset:180; opacity:0} 8%{opacity:.95} 55%{stroke-dashoffset:0; opacity:.95} 82%,100%{stroke-dashoffset:0; opacity:0}}
@keyframes gSpin{0%,40%{opacity:0} 55%,80%{opacity:1} 100%{opacity:0}}
#gest .gHand{position:absolute; left:0; top:0; width:42px; offset-path:var(--gp); offset-rotate:0deg; offset-anchor:34% 7%; animation:gMove 1.9s ease-in-out infinite; filter:drop-shadow(0 3px 4px rgba(0,0,0,.45))}
@keyframes gMove{0%{offset-distance:0%; opacity:0; transform:scale(1.1)} 8%{opacity:1; transform:scale(.94)} 55%{offset-distance:100%; opacity:1; transform:scale(.94)} 70%{offset-distance:100%; transform:scale(1.05)} 82%,100%{offset-distance:100%; opacity:0}}
#gest .gCap{position:absolute; left:50%; bottom:-14px; transform:translateX(-50%); white-space:nowrap; font-family:'Lilita One',Archivo,sans-serif; font-size:15px; color:#2a1a2e; background:#ffd25e; border:2px solid #2a1a2e; border-radius:999px; padding:2px 12px; box-shadow:0 2px 0 rgba(0,0,0,.35)}
#story{position:fixed; inset:0; z-index:45; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:24px; background:#0d0a10; transition:background 1.4s ease, opacity .8s ease; cursor:pointer; -webkit-tap-highlight-color:transparent} /* 12.51: abertura em história */
#story.top{justify-content:flex-start; padding-top:max(26px,9vh)} #story.out{opacity:0; pointer-events:none}
#story .stTxt{margin:0; max-width:min(680px,86vw); font-family:'Lilita One',Archivo,sans-serif; font-size:clamp(22px,4.4vw,34px); line-height:1.25; color:#fff3dc; text-align:center; text-shadow:0 2px 0 rgba(0,0,0,.5), 0 0 22px rgba(255,200,130,.18); min-height:1.3em}
#story .stTxt.in{animation:stIn .5s ease both} @keyframes stIn{from{opacity:0; transform:translateY(6px)}}
#story .stTap{position:absolute; bottom:max(20px,9vh); font-size:14px; font-weight:800; letter-spacing:.04em; color:rgba(255,243,220,.75); opacity:0; transition:opacity .4s} #story .stTap.on{opacity:1; animation:stTap 1.6s ease-in-out infinite} @keyframes stTap{50%{opacity:.4}}
#stSkip{position:absolute; top:calc(env(safe-area-inset-top,0px) + 12px); right:14px; left:auto; width:auto; min-width:0; margin:0; padding:6px 16px; font-size:13px; opacity:.8}
#app.storyOn #start{opacity:0; pointer-events:none; transition:opacity .6s} #app.storyOn #spots{visibility:hidden}
#playTip{position:fixed; z-index:30} #playTip.below{transform:translate(-50%,0)} #playTip.below.go{animation:rtInB .32s cubic-bezier(.2,.8,.3,1.2) both} /* 12.47 */
#q_medio.pulseTip{animation:tipPulse 1.1s ease-in-out infinite; box-shadow:0 0 0 3px #ffd84a, 0 0 18px rgba(255,216,74,.6)} @keyframes tipPulse{50%{transform:scale(1.07)}}
@keyframes rtInB{0%{opacity:0; transform:translate(-50%,10px) scale(.85)} 100%{opacity:1; transform:translate(-50%,0) scale(1)}}
#tutTalk.below::after, #playTip.below::after{bottom:auto; top:-9px; transform:rotate(225deg)}

/* ===== 14.03: MENU NOVO (mockup B com rally, aprovado pelo dono) ===== */
#mRally{position:absolute; left:0; top:0; width:100%; height:100%; pointer-events:none; display:none} #start.hubOn #mRally{display:block}
#start.hubOn .roomTop .logo{display:none} #start.hubOn .roomTop .wallet .rank{display:none}
#start.hubOn .roomTop .wallet{background:#1b1236; border:2.5px solid #1b1236; border-radius:18px; padding:2px 12px 2px 6px} #start.hubOn .roomTop .wallet .coin{background:none; border:0; padding:0; font:400 18px 'Lilita One',sans-serif; color:#fff}
#start.hubOn .roomTop button#gearBtn{width:44px; height:44px; --c:#3a6fd1; --h:#5e8fe8; --l:#1f3f86; --o:#1b1236}
.hOl{text-shadow:1.5px 0 0 #1b1236,-1.5px 0 0 #1b1236,0 1.5px 0 #1b1236,0 -1.5px 0 #1b1236,1px 1px 0 #1b1236,-1px -1px 0 #1b1236,1px -1px 0 #1b1236,-1px 1px 0 #1b1236}
.hTop{position:absolute; left:calc(env(safe-area-inset-left,0px) + 12px); top:10px; right:calc(env(safe-area-inset-right,0px) + 190px); display:flex; justify-content:space-between; align-items:center; pointer-events:none}
.hRank{display:flex; align-items:center; gap:8px; width:262px; pointer-events:auto}
.hRank .rb{flex:none; width:44px; height:44px; border-radius:12px; background:#7b5be0; border:2.5px solid #1b1236; box-shadow:0 3px 0 #4b33a0; display:flex; align-items:center; justify-content:center; font:400 20px 'Lilita One',sans-serif; color:#fff; box-sizing:border-box}
.hBarW{flex:1; display:flex; flex-direction:column; gap:3px; min-width:0}
.hBarH{display:flex; justify-content:space-between; gap:8px; padding-right:24px; font:800 12px/1 'Baloo 2',sans-serif; color:#f3e9ff; white-space:nowrap} .hChalBar .hBarH{padding-right:26px} /* 14.04: o número não fica mais atrás do ícone do fim da barra */ .hBarH b{font:400 14px/1 'Lilita One',sans-serif; color:#fff}
.hBar{position:relative; height:16px; border-radius:9px; background:#1b1236; border:2px solid #1b1236; box-sizing:border-box} .hBar>i{display:block; height:100%; border-radius:7px; background:linear-gradient(#ffe06a,#f4a72a)}
.hBar .hEnd{position:absolute; right:-14px; top:-11px; width:32px; height:32px; border-radius:9px; background:#ff5aa0; border:2.5px solid #1b1236; display:flex; align-items:center; justify-content:center; box-sizing:border-box} .hBar .hEnd svg{width:18px; height:18px}
div.hChalBar{pointer-events:auto; width:210px; margin:0 14px 0 0; padding:0; display:flex; flex-direction:column; gap:3px; cursor:pointer; text-align:left}
.hChalBar .hBar>i{background:linear-gradient(#7fe08a,#2fa84f)} .hChalBar .hEnd{background:#f2b23a; width:34px; height:34px; top:-12px} .hChalBar .hEnd.ready{animation:hubNudge 1.6s infinite}
#hub .hubCol{top:84px; display:flex; flex-direction:column; gap:14px}
#hub button.hubB.hT{width:78px; height:74px; border-radius:14px; padding:0; gap:2px; font-size:13px; --c:#3a6fd1; --h:#5e8fe8; --l:#1f3f86; --o:#1b1236}
#hub button.hubB.hT svg{width:30px; height:30px} #hub button.hubB.hT b{font-size:13px} #hubTour b{font-size:12px !important}
#hub button.hubB .hProg{position:absolute; left:8px; right:8px; bottom:6px; height:5px; border-radius:3px; background:#1b1236} #hub button.hubB .hProg i{display:block; height:100%; width:0; border-radius:3px; background:#7fe08a}
#hub button.hubB .hTag{position:absolute; left:50%; bottom:-11px; transform:translateX(-50%); padding:1px 8px; border-radius:9px; background:#1b1236; font:400 12px/1.25 'Lilita One',sans-serif; color:#fff; white-space:nowrap; text-shadow:none} #hub button.hubB .hTag:empty{display:none}
#hub button.hubB .hTag.go{background:#ff3b4a}
#hub button.hubB.hD{width:66px; height:54px; border-radius:13px; padding:0; gap:1px; --c:#2c5bb8; --h:#4d7ad6; --l:#1a3a7a; --o:#1b1236} #hub button.hubB.hD svg{width:24px; height:24px} #hub button.hubB.hD b{font-size:11px}
.hDock{position:absolute; bottom:calc(env(safe-area-inset-bottom,0px) + 12px); display:flex; gap:10px; pointer-events:none} .hDockL{right:calc(50% + 152px)} .hDockR{left:calc(50% + 152px)}
#hub button.hubB i{display:none}
