function pickLine(i,kind,src){
  const L=(src||LINES[i])[kind]; if(!L) return null; save.bags=save.bags||{}; save.lastLine=save.lastLine||{};
  const key=(CH.id==='bairro'?'':CH.id+':')+(src?'re:':'')+i+':'+kind; let bag=save.bags[key];
  if(!bag||!bag.length){ bag=[...L.keys()]; for(let k=bag.length-1;k>0;k--){ const j=Math.floor(Math.random()*(k+1)); [bag[k],bag[j]]=[bag[j],bag[k]]; }
    if(bag.length>1&&bag[bag.length-1]===save.lastLine[key]) [bag[0],bag[bag.length-1]]=[bag[bag.length-1],bag[0]]; }
  const idx=bag.pop(); save.bags[key]=bag; save.lastLine[key]=idx; persist(); return L[idx];
}
