   Dois celulares. O anfitrião cria a sala (código de 4 letras) e roda a física; o convidado manda a posição da raquete e desenha o estado.
   Os dois se acham pelo servidor gratuito do PeerJS (só a "apresentação", por WebSocket); a partida vai direto entre os aparelhos por WebRTC
   (no mesmo Wi-Fi o tráfego fica na rede local; se a rede bloquear, usa os servidores de retransmissão públicos do PeerJS).
   Teste local: com #netlocal no endereço, a apresentação passa por BroadcastChannel entre abas (sem internet). */
const NET_PREFIX='pplateral-v1-', NET_ABC='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const NET_ICE=[{urls:['stun:stun.l.google.com:19302','stun:stun1.l.google.com:19302','stun:stun.cloudflare.com:3478']},{urls:'turn:eu-0.turn.peerjs.com:3478',username:'peerjs',credential:'peerjsp'},{urls:'turn:us-0.turn.peerjs.com:3478',username:'peerjs',credential:'peerjsp'}];
const netLocal=()=>/netlocal/.test(location.hash);
const SIG_BASE=()=>{ const m=/sig=([^&]+)/.exec(location.hash); return m?decodeURIComponent(m[1]):'wss://0.peerjs.com:443/'; }; // #sig=... só para teste com servidor local
function duelStatus(t){ DUEL.statusT=t||''; $('duelStatus').innerHTML=''; $('duelStatus').append(t||''); const d=sigDiag(); if(t&&d&&!DUEL.live){ const sm=document.createElement('small'); sm.style.cssText='display:block;opacity:.7;font-weight:400;margin-top:4px'; sm.textContent='Servidores: '+d; $('duelStatus').append(sm); } }
// 9.9: a apresentação passa por VÁRIOS servidores ao mesmo tempo (PeerJS + 3 brokers MQTT públicos); vale o primeiro que entregar.
// Cada mensagem leva uma chave (payload.k) para ignorar a cópia que chega pelo outro servidor.
const SIG_MQTT=()=>{ const m=/mqtt=([^&]+)/.exec(location.hash); return m?decodeURIComponent(m[1]).split(',').filter(Boolean):['wss://broker.emqx.io:8084/mqtt','wss://broker.hivemq.com:8884/mqtt','wss://test.mosquitto.org:8081/mqtt']; };
const SIG_NAMES={peerjs:'PeerJS',mqtt1:'EMQX',mqtt2:'HiveMQ',mqtt3:'Mosquitto'};
function sigOpen(id,on){ // on: {open(first), msg(m), err(code), st()}
  if(netLocal()){ const bc=new BroadcastChannel('pp-sig'); bc.onmessage=e=>{ const m=e.data; if(m&&m.dst===id) on.msg(m); }; setTimeout(()=>on.open(true),30);
    return {send:(dst,type,payload)=>bc.postMessage({src:id,dst,type,payload}),close:()=>bc.close(),alive:()=>true,st:{local:'ok'}}; }
  const seen=new Set(), T={}, st={}; let opened=false, dead=0, total=0;
  const got=m=>{ const k=m&&m.payload&&m.payload.k; if(k){ if(seen.has(k)) return; seen.add(k); } on.msg(m); };
  const mk=k=>({ open(){ st[k]='ok'; on.st&&on.st(); if(!opened){ opened=true; on.open(true); } }, msg:got,
    dead(){ if(st[k]==='x') return; st[k]='x'; on.st&&on.st(); if(++dead>=total&&!opened) on.err('net'); } });
  if(!/nopeer/.test(location.hash)){ total++; st.peerjs='…'; const o=mk('peerjs'); T.peerjs=peerOpen(id,{open:o.open,msg:o.msg,err(c){ if(c==='taken') return on.err('taken'); if(c==='expire') return; o.dead(); }}); }
  SIG_MQTT().forEach((u,i)=>{ const k='mqtt'+(i+1); total++; st[k]='…'; T[k]=mqttOpen(u,id,mk(k)); });
  DUEL.sigSt=st;
  return { st, send(dst,type,payload){ const p=Object.assign({},payload,{k:Math.random().toString(36).slice(2,12)}); for(const k in T){ try{ if(k==='peerjs') T[k].send(dst,type,p); else T[k].send(dst,{type,src:id,dst,payload:p}); }catch(_){} } },
    close(){ for(const k in T){ try{ T[k].close(); }catch(_){} } }, alive:()=>Object.values(T).some(t=>t.alive()) };
}
// cliente MQTT 3.1.1 mínimo por WebSocket: cada aparelho assina a própria "caixa de correio" (pplateral/v1/<id>) e publica na do outro
function mqttOpen(url,id,on){ const enc=new TextEncoder(), dec=new TextDecoder();
  const str=s=>{ const b=enc.encode(s); return [b.length>>8,b.length&255,...b]; }, rl=n=>{ const o=[]; do{ let d=n%128; n=Math.floor(n/128); if(n) d|=128; o.push(d); }while(n); return o; };
  const pkt=(t,body)=>new Uint8Array([t,...rl(body.length),...body]), topic=t=>'pplateral/v1/'+t;
  const S={ws:null,closed:false,ok:false,ping:null,tries:0};
  const connect=()=>{ if(S.closed) return; let ws; try{ ws=new WebSocket(url,['mqtt']); }catch(_){ S.closed=true; return on.dead(); } ws.binaryType='arraybuffer'; S.ws=ws; let buf=new Uint8Array(0);
    ws.onopen=()=>ws.send(pkt(0x10,[...str('MQTT'),4,2,0,30,...str('pp'+Math.random().toString(36).slice(2,12))]));
    ws.onmessage=e=>{ const nb=new Uint8Array(e.data), b=new Uint8Array(buf.length+nb.length); b.set(buf); b.set(nb,buf.length); buf=b;
      while(buf.length>=2){ let mul=1,n=0,j=1,d; do{ if(j>=buf.length) return; d=buf[j++]; n+=(d&127)*mul; mul*=128; }while(d&128); if(buf.length<j+n) return;
        const t=buf[0], body=buf.slice(j,j+n), k=t>>4; buf=buf.slice(j+n);
        if(k===2){ if(body[1]!==0){ S.closed=true; try{ ws.close(); }catch(_){} return on.dead(); } ws.send(pkt(0x82,[0,1,...str(topic(id)),0])); }
        else if(k===9){ S.ok=true; S.tries=0; clearInterval(S.ping); S.ping=setInterval(()=>{ try{ ws.send(new Uint8Array([0xC0,0])); }catch(_){} },20000); on.open(); }
        else if(k===3){ const tl=(body[0]<<8)|body[1], off=2+tl+(((t>>1)&3)?2:0); let m; try{ m=JSON.parse(dec.decode(body.slice(off))); }catch(_){ continue; } if(m&&m.dst===id) on.msg(m); } } };
    ws.onclose=()=>{ clearInterval(S.ping); const was=S.ok; S.ok=false; if(S.closed) return; if(!was&&S.tries>=2){ S.closed=true; return on.dead(); } S.tries++; setTimeout(connect,1000*S.tries); }; };
  connect(); document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&!S.closed&&S.ws&&S.ws.readyState>1) connect(); });
  return { send(dst,obj){ if(S.ok&&S.ws&&S.ws.readyState===1) S.ws.send(pkt(0x30,[...str(topic(dst)),...enc.encode(JSON.stringify(obj))])); },
    close(){ S.closed=true; clearInterval(S.ping); try{ S.ws&&S.ws.readyState===1&&S.ws.send(new Uint8Array([0xE0,0])); S.ws&&S.ws.close(); }catch(_){} }, alive:()=>S.ok };
}
function peerOpen(id,on){ // cliente do servidor PeerJS. Reconecta sozinho com o mesmo ID se cair (ex.: app em segundo plano)
  const S={ws:null,hb:null,closed:false,opened:false,tries:0,token:Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)}; // mesmo token nas reconexões: o servidor aceita voltar com o mesmo ID
  const connect=()=>{ if(S.closed) return; let ws; try{ ws=new WebSocket(`${SIG_BASE()}peerjs?key=peerjs&id=${encodeURIComponent(id)}&token=${S.token}&version=1.5.4`); }catch(_){ return on.err('net'); }
    S.ws=ws; ws.onmessage=e=>{ let m; try{ m=JSON.parse(e.data); }catch(_){ return; }
      if(m.type==='OPEN'){ const first=!S.opened; S.opened=true; S.tries=0; clearInterval(S.hb); S.hb=setInterval(()=>{ try{ ws.send(JSON.stringify({type:'HEARTBEAT'})); }catch(_){} },5000); on.open(first); }
      else if(m.type==='ID-TAKEN'){ if(S.opened){ S.tries++; return; } on.err('taken'); } else if(m.type==='ERROR') on.err('error'); else if(m.type==='EXPIRE') on.err('expire',m); else on.msg(m); };
    ws.onclose=()=>{ clearInterval(S.hb); if(S.closed) return; if(!S.opened&&S.tries>=2) return on.err('net'); S.tries++; setTimeout(connect,800*S.tries); }; };
  connect(); document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&!S.closed&&S.ws&&S.ws.readyState>1) connect(); });
  return {send:(dst,type,payload)=>{ if(S.ws&&S.ws.readyState===1) S.ws.send(JSON.stringify({type,dst,payload})); }, close:()=>{ S.closed=true; clearInterval(S.hb); try{ S.ws&&S.ws.close(); }catch(_){} }, alive:()=>!!(S.ws&&S.ws.readyState===1)};
}
// diagnóstico curto da conexão (aparece em letra pequena se falhar), para entender o que a rede fez
function sigDiag(){ const st=DUEL.sigSt||{}; return Object.keys(st).map(k=>`${SIG_NAMES[k]||k} ${st[k]==='ok'?'✓':st[k]==='x'?'✗':'…'}`).join(' · '); }
function netDiag(){ const pc=DUEL.pc, c=DUEL.candN||{}, r=DUEL.rcandN||{}; return (sigDiag()?`servidores: ${sigDiag()}<br>`:'')+`fase ${DUEL.phase||'-'}`+(pc?` · ice ${pc.iceConnectionState} · conexão ${pc.connectionState}`:'')+` · meus ${c.host||0}/${c.srflx||0}/${c.relay||0} · dele ${r.host||0}/${r.srflx||0}/${r.relay||0}`; }
function duelStatusDiag(t){ $('duelStatus').innerHTML=`${t}<br><small style="opacity:.7;font-weight:400">${netDiag()}</small>`; }
function candType(c){ const m=/ typ (\w+)/.exec(c&&c.candidate||''); return m?m[1]:'?'; }
function netReset(keepUI){ clearTimeout(DUEL.timer); clearInterval(DUEL.retry); try{ DUEL.sig&&DUEL.sig.close(); }catch(_){} try{ DUEL.rel&&DUEL.rel.close(); DUEL.fast&&DUEL.fast.close(); DUEL.pc&&DUEL.pc.close(); }catch(_){}
  Object.assign(DUEL,{role:null,live:false,pc:null,rel:null,fast:null,sig:null,code:'',peerId:null,look:null,peerPaddle:null,peerTechs:[],againMe:false,againPeer:false,snap:null,inp:null,seq:0,timer:null,cands:[],phase:null,candN:{},rcandN:{},retry:null,sigSt:null,statusT:''}); FLIP=false;
  if(!keepUI){ $('duelChoose').classList.remove('hidden'); $('duelCodeBox').classList.add('hidden'); $('duelJoinBox').classList.add('hidden'); duelStatus(''); } }
function netSend(o){ const c=DUEL.rel; if(c&&c.readyState==='open'){ try{ c.send(JSON.stringify(o)); }catch(_){} } }
function netPeer(){ // cria a conexão WebRTC e liga os canais (rel: confiável, para eventos; fast: sem reenvio, para estado e raquete)
  const pc=new RTCPeerConnection({iceServers:NET_ICE}); DUEL.pc=pc; DUEL.cands=[];
