async function netFlushCands(){ const q=DUEL.cands||[]; DUEL.cands=[]; for(const c of q){ try{ await DUEL.pc.addIceCandidate(c); }catch(_){} } }
// --- anfitrião: cria a sala
function netHost(tries){ netReset(true); DUEL.role='host'; tries=tries||0; DUEL.phase='sala';
  const code=Array.from({length:4},()=>NET_ABC[Math.floor(Math.random()*NET_ABC.length)]).join(''); DUEL.code=code;
  $('duelChoose').classList.add('hidden'); $('duelJoinBox').classList.add('hidden'); $('duelCodeBox').classList.remove('hidden'); $('duelCode').textContent='····'; duelStatus('Criando a sala…');
  DUEL.sig=sigOpen(NET_PREFIX+code,{ st(){ if(DUEL.phase==='sala') duelStatus(DUEL.statusT); },
    open(first){ $('duelCode').textContent=code; if(!DUEL.pc) duelStatus(first?'Esperando o outro jogador entrar…':'Sala aberta de novo. Esperando o outro jogador…'); },
    err(c){ if(c==='taken'&&tries<4) return netHost(tries+1); if(DUEL.live||c==='expire') return; duelStatus(c==='net'?'Sem conexão com o servidor de salas. Confira a internet e tente de novo.':'Não deu para criar a sala. Tente de novo.'); },
