      else if(m.type==='CANDIDATE'&&m.src===DUEL.peerId){ const t=candType(m.payload.c); DUEL.rcandN[t]=(DUEL.rcandN[t]||0)+1; netAddCand(m.payload.c); } }
  }); }
// --- convidado: entra com o código (repete o pedido a cada 3 s até a sala responder)
function netJoin(){ const code=($('duelInput').value||'').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,4); if(code.length<4) return duelStatus('Digite as 4 letras do código.');
